"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4719],{36085:e=>{e.exports=JSON.parse('{"functions":[{"name":"defaults","desc":"The starting configuration, written to the singleton by `bootstrap`.\\n\\nThe four radii start at zero because they are outputs \u2014 the `observers`\\nsystem derives them from `viewDistanceCells` on its first pass.","params":[],"returns":[{"desc":"A fresh config table.","lua_type":"MazeConfig"}],"function_type":"static","source":{"line":52,"path":"src/main/shared/utils/budget.luau"}},{"name":"deadlineFrom","desc":"The `os.clock()` instant this frame\'s pipeline work must stop at.","params":[{"name":"config","desc":"","lua_type":"MazeConfig"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":70,"path":"src/main/shared/utils/budget.luau"}}],"properties":[{"name":"DEFAULT_FRAME_MS","desc":"Milliseconds per frame the whole maze pipeline may spend.\\n\\nFour is the smallest allowance that still drains a chunk\'s walls within a\\nframe or two of the chunk arriving, which is what keeps the build backlog at\\nzero for a walking player. Smaller is counterproductive rather than merely\\nslower: whatever does not fit carries over, and every stage then repays its\\nper-frame setup against a backlog that never clears. Larger buys throughput\\nonly a teleporting player could use, at the cost of pushing the server frame\\npast the 16.6ms a 60Hz tick allows.","lua_type":"number","source":{"line":41,"path":"src/main/shared/utils/budget.luau"}}],"types":[],"name":"budget","desc":"The maze pipeline\'s frame allowance: its defaults, and the one calculation\\nthat turns it into a deadline.\\n\\nThere is a single budget for the whole pipeline rather than one per stage.\\nIndependent slices summed to more than a frame and gave no stage priority\\nover any other \u2014 whichever phase happened to run first won. One allowance\\nconsumed in phase order makes priority explicit and keeps the total bounded.\\n\\nNothing here touches the world. Systems read `MazeConfig` and `MazeFrame` and\\npass the values in.\\n\\n```lua\\nlocal frame = world:get(components.MazeFrame, components.MazeFrame)\\n-- ... do work until os.clock() >= frame.deadline\\n```","tags":["shared-util"],"source":{"line":21,"path":"src/main/shared/utils/budget.luau"}}')}}]);